select
count(1) as value
from event_record a
where a.event_time between #{date.startTime} and #{date.endTime}
and a.door_index_code in

    #{item}


    and a.event_result=#{param.eventResult}

SELECT a.event_way as name, count(1) as value FROM `event_record` a inner join door_device b on a.door_index_code=b.out_business_id where a.event_time between #{date.startTime} and #{date.endTime} and b.business_id in
#{item}
GROUP BY a.event_way

SELECT event_result as name,count(1) as value
FROM `event_record` a
where a.event_time between #{date.startTime} and #{date.endTime}
and a.door_index_code in

    #{item}

group by event_result

SELECT in_and_out_type as name, count(1) as value
FROM `event_record` a
inner join door_device b on a.door_index_code=b.out_business_id
where a.event_time between #{date.startTime} and #{date.endTime}
and b.business_id in

    #{item}

SELECT event_name as name,count(1) as value FROM `event_record` a where a.event_time between #{date.startTime} and #{date.endTime} and event_result='DO_REFUSE' and a.door_index_code in
#{item}
GROUP BY event_name ORDER BY COUNT(1) desc

select out_business_id from door_device where business_id in
#{id}
group by out_business_id

SELECT count(1) as value FROM door_device where business_id in
#{id}
and status = '1'

SELECT count(1) as value FROM door_device where business_id in
#{id}
and (status != '1' or status is null)
